-- Optional illustrative data. Run after schema.sql. Safe to run again.
-- Sample photos and product specifications are not a real catalog.
BEGIN;
ON CONFLICT(id) DO NOTHING;
SELECT p.id,s.size,c.color,p.sku,(p.stock/(greatest(cardinality(p.sizes),1)*greatest(cardinality(p.colors),1)))+CASE WHEN row_number() OVER(PARTITION BY p.id ORDER BY s.size,c.color)<=p.stock%(greatest(cardinality(p.sizes),1)*greatest(cardinality(p.colors),1)) THEN 1 ELSE 0 END
FROM public.products p CROSS JOIN LATERAL unnest(CASE WHEN cardinality(p.sizes)>0 THEN p.sizes ELSE ARRAY['']::text[] END) s(size) CROSS JOIN LATERAL unnest(CASE WHEN cardinality(p.colors)>0 THEN p.colors ELSE ARRAY['']::text[] END) c(color)
WHERE p.id IN ('f0000001-0000-4000-8000-000000000001','f0000002-0000-4000-8000-000000000002','f0000003-0000-4000-8000-000000000003','f0000004-0000-4000-8000-000000000004','f0000005-0000-4000-8000-000000000005','f0000006-0000-4000-8000-000000000006','f0000007-0000-4000-8000-000000000007','f0000008-0000-4000-8000-000000000008')
ON CONFLICT(product_id,size,color) DO NOTHING;
COMMIT;
