INSERT INTO public.store_settings(id,data) VALUES(1,'{"name":"FORME","tagline":"Your next looks good.","announcement":"NEW SEASON. SAME YOU. MORE POSSIBILITIES.","accent":"#111111","currency":"USD","catalog_mode":"fashion","hero_title":"NEXT\nSTARTS NOW.","hero_description":"New-season energy. Everyday icons. The pieces you make your own.","hero_image":"/images/hero-women.jpg","story_image":"/images/studio.jpg","story_title":"A little less.\nA lot more you.","story_description":"Style is personal. Your wardrobe should be, too. Explore a thoughtful edit of easy layers, useful essentials, and the pieces that bring it all together.","contact_email":"","contact_phone":"","delivery_policy":"Delivery options and payment are confirmed by the store after you submit an order request. This sample store does not process real purchases.","returns_policy":"The store will share its return and exchange terms before confirming your order. Replace this sample policy with your own in Store Studio.","demo":true,"hero_men_image":"/images/hero-men.jpg","shipping_cents":0,"free_shipping_threshold_cents":10000,"payment_provider":"stripe"}'::jsonb) ON CONFLICT(id) DO NOTHING;
